/**
 * Strip `// line comments`, `/* block comments */`, and string literals
 * (single, double, backtick) from TypeScript source — replacing each with
 * spaces of the same length so character offsets stay aligned. The regex
 * then can't match identifiers inside comments / error message strings.
 */
function stripCommentsAndStrings(src: string): string {
  const out: string[] = [];
  let i = 0;
  while (i < src.length) {
    const ch = src[i];
    const next = src[i + 1];
    // Line comment
    if (ch === "/" && next === "/") {
      while (i < src.length && src[i] !== "\n") {
        out.push(src[i] === "\n" ? "\n" : " ");
        i++;
      }
      continue;
    }
    // Block comment
    if (ch === "/" && next === "*") {
      out.push("  ");
      i += 2;
      while (i < src.length && !(src[i] === "*" && src[i + 1] === "/")) {
        out.push(src[i] === "\n" ? "\n" : " ");
        i++;
      }
      if (i < src.length) {
        out.push("  ");
        i += 2;
      }
      continue;
    }
    // String literal (single, double, backtick)
    if (ch === '"' || ch === "'" || ch === "`") {
      const quote = ch;
      out.push(quote);
      i++;
      while (i < src.length && src[i] !== quote) {
        if (src[i] === "\\" && i + 1 < src.length) {
          // Escape sequence — keep two chars as spaces.
          out.push(src[i] === "\n" ? "\n" : " ");
          out.push(src[i + 1] === "\n" ? "\n" : " ");
          i += 2;
          continue;
        }
        // Template-literal `${...}` interpolation — preserve so call sites
        // inside template strings still match. (None today, but cheap to
        // honor.)
        if (quote === "`" && src[i] === "$" && src[i + 1] === "{") {
          let depth = 1;
          out.push("$");
          out.push("{");
          i += 2;
          while (i < src.length && depth > 0) {
            if (src[i] === "{") depth++;
            else if (src[i] === "}") depth--;
            if (depth === 0) break;
            out.push(src[i]);
            i++;
          }
          if (i < src.length) {
            out.push("}");
            i++;
          }
          continue;
        }
        out.push(src[i] === "\n" ? "\n" : " ");
        i++;
      }
      if (i < src.length) {
        out.push(quote);
        i++;
      }
      continue;
    }
    out.push(ch);
    i++;
  }
  return out.join("");
}

